-- Values must match the published legacy row exactly, before and after.
DO $$
DECLARE v_diff integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.scenario_probabilities
                  WHERE conflict_day = 221 AND scenario_a = 23 AND scenario_b = 44 AND scenario_c = 5 AND scenario_d = 28
                    AND scenario_e IS NULL) THEN
    RAISE EXCEPTION 'scenario_probabilities Day 221 is not 23/44/5/28/NULL; refusing to import a different row';
  END IF;
END $$;
SET CONSTRAINTS ALL IMMEDIATE;   -- run the deferred group/sum checks now so the comparison sees a valid state
DO $$
DECLARE v_missing integer; v_extra integer; v_days text;
BEGIN
  SELECT count(*) INTO v_missing FROM (SELECT * FROM public.scenario_probabilities
                                       EXCEPT SELECT * FROM public.v_scenario_probabilities_compat) x;
  SELECT count(*) INTO v_extra   FROM (SELECT * FROM public.v_scenario_probabilities_compat
                                       EXCEPT SELECT * FROM public.scenario_probabilities) x;
  IF v_missing <> 0 OR v_extra <> 0 THEN
    SELECT string_agg(conflict_day::text, ',') INTO v_days FROM (SELECT conflict_day, scenario_a, scenario_b, scenario_c, scenario_d, scenario_e, updated_at FROM public.scenario_probabilities
      EXCEPT SELECT conflict_day, scenario_a, scenario_b, scenario_c, scenario_d, scenario_e, updated_at FROM public.v_scenario_probabilities_compat) y;
    RAISE EXCEPTION 'compatibility view differs from scenario_probabilities (% missing, % extra; days %). Import every published day before applying.', v_missing, v_extra, v_days;
  END IF;
END $$;

COMMIT;
